# RW2DM_NAMES: SetObjectName and SetUserText: names and user text on objects. The script rw2dm_names_script.txt is generated by rw2dm_gen.py. The oracle is exact set / string logic on four objects (ids 1..4 = Point, Line, Plane, Box):
# after each step the objects that List reaches are compared, as id:kind:layer[:name], with the expected list exactly (and the printed message lines with their patterns).
RW2_NAMES_OUT=""
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RW2_NAMES_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rw2dm_names_script.txt" 2>&1)" || { echo "$RW2_NAMES_OUT" | tail -40; echo "FAIL RW2DM_NAMES_run: script exited non-zero"; fail=1; RW2_NAMES_OUT=""; }
else
  RW2_NAMES_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rw2dm_names_script.txt" 2>&1)" || { echo "$RW2_NAMES_OUT" | tail -40; echo "FAIL RW2DM_NAMES_run: script exited non-zero"; fail=1; RW2_NAMES_OUT=""; }
fi
rw2_names_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW2BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW2BEGIN_/ { exit } on { print }' <<<"$RW2_NAMES_OUT"; }
# rw2_names_state STEP EXPECTED DESC [PATTERN...]: the objects listed in the step read exactly EXPECTED ("-" = none); each PATTERN must match a printed line of the step
rw2_names_state() {
  local blk got name desc pat bad want; name="$1"; want="$2"; desc="$3"; blk="$(rw2_names_block "$name")"
  got="$({ grep -E '^history: Object [0-9]+ \(' <<<"$blk" || true; } | sed -E "s/^history: Object ([0-9]+) \(([^)]*)\) layer ([^ ]+) name '(.*)'\$/\1:\2:\3:\4/; s/^history: Object ([0-9]+) \(([^)]*)\) layer ([^ ]+)\$/\1:\2:\3/" | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  bad=""
  shift 3
  for pat in "$@"; do grep -qE "^history: $pat" <<<"$blk" || bad="$bad [$pat]"; done
  if [ "$got" = "$want" ] && [ -z "$bad" ]; then echo "ok   RW2DM_NAMES_$name: $desc (objects: $got)"
  else echo "FAIL RW2DM_NAMES_$name: $desc (listed '$got', expected '$want'; missing message patterns:${bad:- none})"; fail=1; { grep -E '^history: (Object|!|[A-Za-z]+:)' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}
rw2_names_state name "1:point:Default 2:curve:Default:Beam 3:surface:Default 4:polysurface:Default" "SetObjectName Beam on object 2 names it; the other objects stay unnamed" "SetObjectName: named 1 object\(s\) 'Beam'"
rw2_names_state selname "2:curve:Default:Beam" "SelName Beam selects exactly the named object 2" "1 object\(s\) named 'Beam' selected"
rw2_names_state rename "4:polysurface:Default:Slab" "SetObjectName on 4 names a second object Slab; SelName Slab reaches only 4, SelName Beam still only 2" "1 object\(s\) named 'Slab' selected"
rw2_names_state usertext "1:point:Default 3:surface:Default" "SetUserText Phase One on 1 and 3: SelKeyValue Phase One selects exactly 1 and 3" "SetUserText: Phase = One on 2 object\(s\)" "SelKeyValue: 2 object\(s\) with Phase=One selected"
rw2_names_state usertext_other "2:curve:Default:Beam" "a different value on 2: SelKeyValue Phase Two reaches only 2 (the name Beam is kept) and SelKey Phase reaches 1, 2, 3" "SelKeyValue: 1 object\(s\) with Phase=Two selected"
rw2_names_state selkey "1:point:Default 2:curve:Default:Beam 3:surface:Default" "SelKey Phase selects every object carrying the key: 1, 2 and 3" "3 object\(s\) selected"
